// Made for @sableRaph's weekly creative challenge on Twitch
// https://www.twitch.tv/sableraph
// "Textile"

const palette = ["#294984", "#6ca0a7", "#ffc789", "#df5f50", "#5a3034", "#fff1dd"];

const MAX_SEED = 112358; // arbitrary big number
const N = 2; // recursion level
let colorMode;

function setup() {
  createCanvas(625, 625);
  // noLoop() removed for animation
  noStroke();
}

function draw() {
  colorMode = floor(random(2));
  divide(0, 0, width, random(MAX_SEED), N);
}

// Central and axial symmetry!
// 0 1 2 1 0
// 1 3 4 3 1
// 2 4 5 4 2
// 1 3 4 3 1
// 0 1 2 1 0

function divide(x, y, s, seed, n) {
  if (n == 0) {
    makeSquare(x, y, s, seed);
    return;
  }

  randomSeed(seed);
  let seed0 = random(MAX_SEED);
  let seed1 = random(MAX_SEED);
  let seed2 = random(MAX_SEED);
  let seed3 = random(MAX_SEED);
  let seed4 = random(MAX_SEED);
  let seed5 = random(MAX_SEED);

  let seeds = [
    [seed0, seed1, seed2, seed1, seed0],
    [seed1, seed3, seed4, seed3, seed1],
    [seed2, seed4, seed5, seed4, seed2],
    [seed1, seed3, seed4, seed3, seed1],
    [seed0, seed1, seed2, seed1, seed0]
  ];

  for (let i = 0; i < 5; i++) {
    for (let j = 0; j < 5; j++) {
      divide(x+i*s/5, y+j*s/5, s/5, seeds[i][j], n-1);
    }
  }
}

function makeSquare(x, y, s, seed) {
  randomSeed(seed);
  let color0, color1, color2, color3, color4, color5;

  if (colorMode == 0) {
    // random colors, can be repeated
    color0 = random(palette);
    color1 = random(palette);
    color2 = random(palette);
    color3 = random(palette);
    color4 = random(palette);
    color5 = random(palette);
  } else {
    // every color once, in a random order
    let indices = [0, 1, 2, 3, 4, 5];
    color0 = palette[indices.splice(floor(random(indices.length)), 1)];
    color1 = palette[indices.splice(floor(random(indices.length)), 1)];
    color2 = palette[indices.splice(floor(random(indices.length)), 1)];
    color3 = palette[indices.splice(floor(random(indices.length)), 1)];
    color4 = palette[indices.splice(floor(random(indices.length)), 1)];
    color5 = palette[indices.splice(floor(random(indices.length)), 1)];
  }

  let colors = [
    [color0, color1, color2, color1, color0],
    [color1, color3, color4, color3, color1],
    [color2, color4, color5, color4, color2],
    [color1, color3, color4, color3, color1],
    [color0, color1, color2, color1, color0]
  ];

  for (let i = 0; i < 5; i++) {
    for (let j = 0; j < 5; j++) {
      fill(colors[i][j]);
      square(x+i*s/5, y+j*s/5, s/5);
    }
  }
}
